float hash21(float2 p)
{
    p = frac(p * float2(123.34f, 456.21f));
    p += dot(p, p + 45.32f);
    return frac(p.x * p.y);
}

float simpleNoise(float2 uv)
{
    float2 i = floor(uv);
    float2 f = frac(uv);
    float a = hash21(i);
    float b = hash21(i + float2(1.0f, 0.0f));
    float c = hash21(i + float2(0.0f, 1.0f));
    float d = hash21(i + float2(1.0f, 1.0f));
    float2 u = f * f * (3.0f - 2.0f * f);
    return lerp(lerp(a, b, u.x), lerp(c, d, u.x), u.y);
}

float4 node141_func(float4 color)
{
float3 x = max(color.rgb, 0.0f);

    x = x / (1.0f + x);

    return float4(x, color.a);
}


float2 voronoiHash22(float2 p)
{
    p = float2(dot(p, float2(127.1f, 311.7f)), dot(p, float2(269.5f, 183.3f)));
    return frac(sin(p) * 43758.5453f);
}

float3 voronoi(float2 uv, float randomness)
{
    float2 baseCell = floor(uv);
    float2 f = frac(uv);

    float  d1 = 8.0f;
    float  d2 = 8.0f;
    float2 closest = float2(0.0f, 0.0f);

    [unroll] for (int y = -1; y <= 1; ++y)
    [unroll] for (int x = -1; x <= 1; ++x)
    {
        float2 cell = float2(x, y);
        float2 pt   = cell + voronoiHash22(baseCell + cell) * randomness;
        float  d    = length(pt - f);

        if (d < d1)
        {
            d2 = d1;
            d1 = d;
            closest = baseCell + cell;
        }
        else if (d < d2)
        {
            d2 = d;
        }
    }

    float id = frac(dot(closest, float2(0.3183099f, 0.7834f)));
    return float3(d1, id, d2 - d1);
}


